import { NgModule, ModuleWithProviders } from '@angular/core';
import { CommonModule } from '@angular/common';

import {
	NgTranscludeDirective,
	TabHeadingDirective,
	TabsetConfig,
	TabsModule as ngxTabsModule
} from 'ngx-bootstrap/tabs';

import { TabsetComponent } from './tabset.component';
import { TabpanelComponent } from './tabpanel.component';
import { MessageModule } from 'espd-common/i18n';

@NgModule({
	imports: [
		CommonModule,
		ngxTabsModule,
		MessageModule
	],
	declarations: [
		TabsetComponent,
		TabpanelComponent
	],
	exports: [
		TabHeadingDirective,
		NgTranscludeDirective,

		TabsetComponent,
		TabpanelComponent
	]
})
export class TabsModule {
	public static forRoot(): ModuleWithProviders<TabsModule> {
		return { ngModule: TabsModule, providers: [TabsetConfig] };
	}
}