
import {
	Component,
	ElementRef,
	EventEmitter,
	HostBinding,
	inject,
	Input,
	OnDestroy,
	OnInit,
	Output
} from '@angular/core';

import { MessageConfig } from 'espd-common/i18n';
import { TabsetComponent } from './tabset.component';

@Component({
	selector: 'espd-tabpanel',
	templateUrl: 'tabpanel.component.html',
	styleUrls: ['tabpanel.component.scss'],
	host: {
		role: 'tabpanel',
		'[class.tab-pane]': 'true'
	},
	standalone: false
})
export class TabpanelComponent implements OnInit, OnDestroy {

	private static nextId = 0;

	/** tab header text */
	@Input() public heading?: string | MessageConfig;

	/** tab id. The same id with suffix '-link' will be added to the corresponding &lt;li&gt; element  */
	@HostBinding('attr.id')
	@Input() public id?: string;

	/** if true tab can not be activated */
	@Input() public disabled = false;

	@HostBinding('attr.aria-labelledby')
	get label(): string {
		return this.id + '-link';
	}

	@HostBinding('tabindex')
	get tabindex(): number {
		return this.active ? 0 : -1;
	}

	@HostBinding('attr.hidden')
	get hidden(): any {
		return this.isActive ? null : 'hidden';
	}

	/** tab active state toggle */
	@Input()
	get active(): boolean | undefined {
		return this.isActive;
	}

	set active(active: boolean | undefined) {
		if (this.isActive === active) {
			return;
		}
		if ((this.disabled && active) || !active) {
			if (this.isActive && !active) {
				this.deselect.emit(this);
				this.isActive = active;
			}

			return;
		}

		this.isActive = active;
		this.select.emit(this);
		this.tabset.tabs.forEach((tab: TabpanelComponent) => {
			if (tab !== this) {
				tab.active = false;
			}
		});
	}

	/** fired when tab became active, $event:Tab equals to selected instance of Tab component */
	// eslint-disable-next-line @angular-eslint/no-output-native
	@Output() public readonly select = new EventEmitter<TabpanelComponent>();
	/** fired when tab became inactive, $event:Tab equals to deselected instance of Tab component */
	@Output() public readonly deselect = new EventEmitter<TabpanelComponent>();
	/** fired before tab will be removed, $event:Tab equals to instance of removed tab */
	@Output() public readonly removed = new EventEmitter<TabpanelComponent>();

	protected isActive?: boolean;

	/** An ID to identify this component instance. Used for generating unique IDs in the DOM */
	private _id?: number;

	public elementRef = inject(ElementRef);
	private tabset = inject(TabsetComponent);

	constructor() {
		this.tabset.addTab(this);
	}

	public ngOnInit(): void {
		if (!this.id) {
			this._id = TabpanelComponent.nextId++;
			this.id = 'panel_' + this._id;
		}
	}

	public ngOnDestroy(): void {
		this.tabset.removeTab(this, { reselect: false, emit: false });
	}
}