
import {
	Component,
	ElementRef,
	inject,
	Input,
	OnDestroy,
	QueryList,
	Renderer2,
	ViewChildren
} from '@angular/core';
import { TabsetConfig } from 'ngx-bootstrap/tabs';

// import { TabsetConfig } from 'ngx-bootstrap/tabs';

import { TabpanelComponent } from './tabpanel.component';

enum Key {
	Enter = 13,
	Space = 32,
	Left = 37,
	Right = 39,
	Up = 38,
	Down = 40
}

@Component({
	selector: 'espd-tabset',
	templateUrl: 'tabset.component.html',
	styleUrls: ['tabset.component.scss'],
	standalone: false
})
export class TabsetComponent implements OnDestroy {

	@ViewChildren('tabButton')
	public tabButtonElements?: QueryList<ElementRef>;

	/** if true tabs fill the container and have a consistent width */
	@Input()
	public justified = false;

	public tabs: TabpanelComponent[] = [];

	private isDestroyed = false;
	private focusedTab = 0;

	private config = inject(TabsetConfig);
	private renderer = inject(Renderer2);

	constructor() {
		Object.assign(this, this.config);
	}

	public ngOnDestroy(): void {
		this.isDestroyed = true;
	}

	public addTab(tab: TabpanelComponent): void {
		this.tabs.push(tab);
		tab.active = this.tabs.length === 1 && typeof tab.active === 'undefined';
		this.focusedTab = this.getActiveTabIndex();
	}

	public removeTab(tab: TabpanelComponent, options = { reselect: true, emit: true }): void {
		const index = this.tabs.indexOf(tab);
		if (index === -1 || this.isDestroyed) {
			return;
		}
		// Select a new tab if the tab to be removed is selected and not destroyed
		if (options.reselect && tab.active && this.hasAvailableTabs(index)) {
			const newActiveIndex = this.getClosestTabIndex(index);
			this.tabs[newActiveIndex].active = true;
		}
		if (options.emit) {
			tab.removed.emit(tab);
		}
		this.tabs.splice(index, 1);
		if (tab.elementRef.nativeElement.parentNode) {
			this.renderer.removeChild(
				tab.elementRef.nativeElement.parentNode,
				tab.elementRef.nativeElement
			);
		}
	}

	public onKey(event: KeyboardEvent): void {
		event.preventDefault();
		if (this.focusedTab !== null) {
			const key: number = event.keyCode;
			if (key === Key.Enter || key === Key.Space) {
				this.selectTab(this.tabs[this.focusedTab]);
			} else if (key === Key.Right || key === Key.Down) {
				this.focusNextTab();
			} else if (key === Key.Left || key === Key.Up) {
				this.focusPreviousTab();
			}
		}
	}

	public selectTab(tab: TabpanelComponent): void {
		tab.active = true;
	}

	protected getClosestTabIndex(index: number): number {
		const tabsLength = this.tabs.length;
		if (!tabsLength) {
			return -1;
		}

		for (let step = 1; step <= tabsLength; step += 1) {
			const prevIndex = index - step;
			const nextIndex = index + step;
			if (this.tabs[prevIndex] && !this.tabs[prevIndex].disabled) {
				return prevIndex;
			}
			if (this.tabs[nextIndex] && !this.tabs[nextIndex].disabled) {
				return nextIndex;
			}
		}

		return -1;
	}

	protected hasAvailableTabs(index: number): boolean {
		const tabsLength = this.tabs.length;
		if (!tabsLength) {
			return false;
		}

		for (let i = 0; i < tabsLength; i += 1) {
			if (!this.tabs[i].disabled && i !== index) {
				return true;
			}
		}

		return false;
	}

	private focusNextTab() {
		let currentFocusIndex: number = this.focusedTab || this.getActiveTabIndex();
		currentFocusIndex++;
		if (currentFocusIndex >= this.tabs.length) {
			currentFocusIndex = 0;
		}
		this.focusTab(currentFocusIndex);
	}

	private focusPreviousTab() {
		let currentFocusIndex: number = this.focusedTab || this.getActiveTabIndex();
		currentFocusIndex--;
		if (currentFocusIndex < 0) {
			currentFocusIndex = this.tabs.length - 1;
		}
		this.focusTab(currentFocusIndex);
	}

	private focusTab(index: number) {
		this.focusedTab = index;
		if (this.tabButtonElements) {
			const buttonRef: ElementRef = this.tabButtonElements.toArray()[index];
			buttonRef.nativeElement.focus();
		}
	}

	private getActiveTabIndex() {
		return this.tabs.findIndex(tab => tab.active);
	}
}